 <!DOCTYPE html>
 <html lang="en">
   <head>
     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Notification Preferences</title>
     <style>
       :root {
         color-scheme: dark;
         --bg: #0b1020;
         --panel: rgba(17, 24, 39, 0.9);
         --panel-border: rgba(148, 163, 184, 0.16);
         --text: #e5eefc;
         --muted: #9aa9c2;
         --accent: #7c3aed;
         --accent-strong: #a855f7;
         --focus: #c4b5fd;
         --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         background:
           radial-gradient(circle at top, rgba(124, 58, 237, 0.22), transparent 34%),
           linear-gradient(180deg, #070b16 0%, #0b1020 100%);
         color: var(--text);
         display: grid;
         place-items: center;
         padding: 24px;
       }

       .card {
         width: min(100%, 560px);
         background: var(--panel);
         border: 1px solid var(--panel-border);
         border-radius: 24px;
         box-shadow: var(--shadow);
         padding: 32px;
         backdrop-filter: blur(18px);
       }

       h1 {
         margin: 0 0 8px;
         font-size: clamp(1.5rem, 2vw, 2rem);
         letter-spacing: -0.03em;
       }

       .subtitle {
         margin: 0 0 24px;
         color: var(--muted);
         line-height: 1.5;
       }

       .form-field {
         padding: 20px;
         border: 1px solid rgba(148, 163, 184, 0.14);
         border-radius: 18px;
         background: rgba(15, 23, 42, 0.65);
       }

       fieldset {
         border: 0;
         margin: 0;
         padding: 0;
       }

       legend {
         font-size: 1.05rem;
         font-weight: 650;
         margin-bottom: 16px;
       }

       .options {
         display: grid;
         gap: 12px;
       }

       .option {
         display: flex;
         align-items: center;
         gap: 12px;
         padding: 14px 16px;
         border: 1px solid rgba(148, 163, 184, 0.14);
         border-radius: 14px;
         background: rgba(255, 255, 255, 0.02);
         transition: border-color 0.18s ease, transform 0.18s ease, background 0.18s ease;
       }

       .option:hover {
         border-color: rgba(168, 85, 247, 0.45);
         transform: translateY(-1px);
         background: rgba(124, 58, 237, 0.08);
       }

       .option input {
         width: 18px;
         height: 18px;
         accent-color: var(--accent);
       }

       .option span {
         font-size: 0.98rem;
       }

       .actions {
         margin-top: 24px;
         display: flex;
         gap: 12px;
         align-items: center;
       }

       button {
         appearance: none;
         border: 0;
         border-radius: 999px;
         padding: 12px 18px;
         font: inherit;
         font-weight: 650;
         color: white;
         background: linear-gradient(135deg, var(--accent), var(--accent-strong));
         box-shadow: 0 12px 28px rgba(124, 58, 237, 0.32);
         cursor: pointer;
       }

       button:hover {
         filter: brightness(1.05);
       }

       button:focus-visible,
       input:focus-visible {
         outline: 3px solid var(--focus);
         outline-offset: 3px;
       }

       .status {
         min-height: 1.4em;
         color: var(--muted);
         font-size: 0.95rem;
       }
     </style>
   </head>
   <body>
     <main id="app"></main>

     <script>
       const createOption = (label, value, checked = false) => `
         <label class="option">
           <input type="radio" name="notificationPreference" value="${value}" ${checked ? "checked" : ""} required />
           <span>${label}</span>
         </label>
       `;

       const NotificationQuestion = () => `
         <section class="card" aria-labelledby="page-title">
           <h1 id="page-title">Notification Preferences</h1>
           <p class="subtitle">Choose one way you'd like to receive updates.</p>

           <form id="notification-form" novalidate>
             <div class="form-field">
               <fieldset>
                 <legend>How do you prefer to receive notifications?</legend>
                 <div class="options" role="radiogroup" aria-label="How do you prefer to receive notifications?">
                   ${createOption("Email", "email", true)}
                   ${createOption("SMS", "sms")}
                   ${createOption("Push Notifications", "push")}
                 </div>
               </fieldset>
             </div>

             <div class="actions">
               <button type="submit">Submit</button>
               <div class="status" id="form-status" aria-live="polite"></div>
             </div>
           </form>
         </section>
       `;

       document.getElementById("app").innerHTML = NotificationQuestion();

       document.getElementById("notification-form").addEventListener("submit", (event) => {
         event.preventDefault();
         const selected = document.querySelector('input[name="notificationPreference"]:checked');
         document.getElementById("form-status").textContent = selected
           ? `Selected: ${selected.value === "push" ? "Push Notifications" : selected.value.charAt(0).toUpperCase() + selected.value.slice(1)}`
           : "Please select an option.";
       });
     </script>
   </body>
 </html>

